CREATE TABLE IF NOT EXISTS timetable (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID REFERENCES schools(id), subject_id UUID REFERENCES subjects(id), teacher_id UUID REFERENCES profiles(id), class TEXT NOT NULL, day_of_week INT NOT NULL CHECK (day_of_week BETWEEN 0 AND 6), start_time TIME NOT NULL, end_time TIME NOT NULL, room TEXT, created_at TIMESTAMPTZ DEFAULT NOW());  
